#!/usr/bin/env python3
import socket
import sys
import time
import argparse

def send_smtp_command(sock, command):
    """Send an SMTP command and return the response."""
    sock.sendall(f"{command}\r\n".encode())
    response = b""
    while True:
        data = sock.recv(4096)
        response += data
        if not data or response.endswith(b"\r\n"):
            break
    return response.decode('utf-8', errors='ignore')

def check_vrfy_expn(target, port=25, timeout=10):
    """Check for VRFY/EXPN information disclosure vulnerabilities."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        sock.connect((target, port))
        
        # Get initial banner
        banner = send_smtp_command(sock, "")
        print(f"[+] Server Banner: {banner.strip()}")
        
        # Test VRFY with a likely valid address
        print("[*] Testing VRFY with a likely valid address...")
        start_time = time.time()
        vrfy_valid = send_smtp_command(sock, "VRFY admin")
        valid_time = time.time() - start_time
        print(f"[+] VRFY admin response: {vrfy_valid.strip()}")
        print(f"[+] VRFY admin response time: {valid_time:.4f} seconds")
        
        # Test VRFY with an unlikely valid address
        print("[*] Testing VRFY with an unlikely valid address...")
        start_time = time.time()
        vrfy_invalid = send_smtp_command(sock, "VRFY nonexistentuser12345")
        invalid_time = time.time() - start_time
        print(f"[+] VRFY nonexistentuser12345 response: {vrfy_invalid.strip()}")
        print(f"[+] VRFY nonexistentuser12345 response time: {invalid_time:.4f} seconds")
        
        # Test EXPN with a likely valid list
        print("[*] Testing EXPN with a likely valid list...")
        start_time = time.time()
        expn_valid = send_smtp_command(sock, "EXPN staff")
        valid_time = time.time() - start_time
        print(f"[+] EXPN staff response: {expn_valid.strip()}")
        print(f"[+] EXPN staff response time: {valid_time:.4f} seconds")
        
        # Test EXPN with an unlikely valid list
        print("[*] Testing EXPN with an unlikely valid list...")
        start_time = time.time()
        expn_invalid = send_smtp_command(sock, "EXPN nonexistentlist12345")
        invalid_time = time.time() - start_time
        print(f"[+] EXPN nonexistentlist12345 response: {expn_invalid.strip()}")
        print(f"[+] EXPN nonexistentlist12345 response time: {invalid_time:.4f} seconds")
        
        sock.close()
        
        # Analyze results
        print("\n[!] Analysis:")
        if "252" in vrfy_valid and "252" in vrfy_invalid:
            print("[+] Server returns 252 for both valid and invalid addresses (Compliant)")
        else:
            print("[-] Server returns different codes for valid and invalid addresses (Vulnerable)")
        
        if abs(valid_time - invalid_time) > 0.1:
            print("[-] Significant timing difference detected (Potential Timing Side-Channel)")
        else:
            print("[+] No significant timing difference detected")
        
    except Exception as e:
        print(f"[!] Error: {e}")

def main():
    parser = argparse.ArgumentParser(description="VRFY/EXPN Information Disclosure PoC")
    parser.add_argument("target", help="Target SMTP server hostname or IP")
    parser.add_argument("--port", type=int, default=25, help="SMTP port (default: 25)")
    args = parser.parse_args()
    
    check_vrfy_expn(args.target, args.port)

if __name__ == "__main__":
    main()